<?php
if(!defined('ABSPATH'))exit;
/** TUFF BEATZ Studio Business OS V14.11 — Cost Basis, Profitability, Revenue Concentration & Client Value */

function tuff_beatz_v1411_cost_categories(){return array(
 'production_labor'=>'Production Labor',
 'musicians'=>'Musicians / Vocalists',
 'engineering'=>'Engineering / Editing',
 'studio'=>'Studio / Room',
 'contractors'=>'Contractors / Freelancers',
 'licensing'=>'Licensing / Assets',
 'travel'=>'Travel / Logistics',
 'other'=>'Other Direct Costs'
);}
function tuff_beatz_v1411_cost_basis($id){$v=get_post_meta((int)$id,'_tb_v1411_cost_basis',true);if(!is_array($v))return array('recorded'=>false,'items'=>array(),'notes'=>'','updated_at'=>'','updated_by'=>0,'total'=>0.0);$items=array();$total=0.0;foreach(tuff_beatz_v1411_cost_categories() as $k=>$label){$amt=max(0,(float)($v['items'][$k]??0));$items[$k]=$amt;$total+=$amt;}return array('recorded'=>true,'items'=>$items,'notes'=>(string)($v['notes']??''),'updated_at'=>(string)($v['updated_at']??''),'updated_by'=>(int)($v['updated_by']??0),'total'=>round($total,2));}
function tuff_beatz_v1411_cost_total($id){$c=tuff_beatz_v1411_cost_basis($id);return (float)$c['total'];}

function tuff_beatz_v1411_cost_metabox(){add_meta_box('tb_v1411_cost_basis','Business OS V14.11 — Project Cost Basis','tuff_beatz_v1411_cost_metabox_render','tb_request','normal','default');}
add_action('add_meta_boxes_tb_request','tuff_beatz_v1411_cost_metabox');
function tuff_beatz_v1411_cost_metabox_render($post){$c=tuff_beatz_v1411_cost_basis($post->ID);wp_nonce_field('tb_v1411_cost_save_'.$post->ID,'tb_v1411_cost_nonce');echo '<p><strong>Direct project costs</strong><br><small>Record only costs attributable to this project. Profitability metrics exclude projects whose cost basis has never been saved.</small></p><div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px">';foreach(tuff_beatz_v1411_cost_categories() as $k=>$label){echo '<label><strong>'.esc_html($label).'</strong><br><input style="width:100%" type="number" min="0" step="0.01" name="tb_v1411_cost['.esc_attr($k).']" value="'.esc_attr((string)($c['items'][$k]??0)).'"></label>';}echo '</div><p><label><strong>Cost Notes</strong><br><textarea style="width:100%;min-height:70px" name="tb_v1411_cost_notes">'.esc_textarea($c['notes']).'</textarea></label></p><p><strong>Recorded Direct Cost: '.esc_html(function_exists('tuff_beatz_money')?tuff_beatz_money($c['total']):'$'.number_format($c['total'],2)).'</strong>';if($c['updated_at'])echo '<br><small>Updated '.esc_html($c['updated_at']).'</small>';echo '</p>';}
function tuff_beatz_v1411_save_cost_basis($id,$post){if($post->post_type!=='tb_request'||(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE))return;if(!isset($_POST['tb_v1411_cost_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tb_v1411_cost_nonce'])),'tb_v1411_cost_save_'.$id)||!current_user_can('edit_post',$id))return;$raw=is_array($_POST['tb_v1411_cost']??null)?wp_unslash($_POST['tb_v1411_cost']):array();$items=array();foreach(tuff_beatz_v1411_cost_categories() as $k=>$label)$items[$k]=max(0,(float)($raw[$k]??0));$record=array('items'=>$items,'notes'=>sanitize_textarea_field(wp_unslash($_POST['tb_v1411_cost_notes']??'')),'updated_at'=>current_time('mysql'),'updated_by'=>get_current_user_id());update_post_meta($id,'_tb_v1411_cost_basis',$record);}
add_action('save_post_tb_request','tuff_beatz_v1411_save_cost_basis',42,2);

function tuff_beatz_v1411_project_profitability($id){$id=(int)$id;$cost=tuff_beatz_v1411_cost_basis($id);$tot=function_exists('tuff_beatz_payment_totals')?tuff_beatz_payment_totals($id):array('total'=>0,'paid'=>0,'balance'=>0);$contract=max(0,(float)($tot['total']??0));$paid=max(0,(float)($tot['paid']??0));$direct=(float)$cost['total'];$contract_profit=$contract-$direct;$cash_contribution=$paid-$direct;$margin=$cost['recorded']&&$contract>0?($contract_profit/$contract)*100:null;return array('id'=>$id,'cost_recorded'=>(bool)$cost['recorded'],'direct_cost'=>$direct,'contract_revenue'=>$contract,'paid'=>$paid,'balance'=>max(0,(float)($tot['balance']??0)),'contract_profit'=>$contract_profit,'cash_contribution'=>$cash_contribution,'margin_percent'=>$margin,'service'=>(string)get_post_meta($id,'_tb_request_service',true),'client_id'=>(int)get_post_field('post_author',$id),'status'=>(string)(get_post_meta($id,'_tb_request_status',true)?:'new'));}

function tuff_beatz_v1411_profitability_intelligence(){
 $q=new WP_Query(array('post_type'=>'tb_request','post_status'=>'publish','posts_per_page'=>500,'fields'=>'ids','orderby'=>'date','order'=>'DESC'));$services=function_exists('tuff_beatz_services')?tuff_beatz_services():array();$projects=array();$service=array();$clients=array();$paid_total=0.0;$cost_total=0.0;$contract_total=0.0;$covered_contract=0.0;$covered_paid=0.0;$covered_count=0;$completed_covered=0;
 foreach($q->posts as $id){$p=tuff_beatz_v1411_project_profitability($id);$projects[]=$p;$uid=$p['client_id'];if(!isset($clients[$uid]))$clients[$uid]=array('client_id'=>$uid,'paid'=>0.0,'projects'=>0,'completed'=>0,'name'=>'');$clients[$uid]['paid']+=$p['paid'];$clients[$uid]['projects']++;if($p['status']==='completed')$clients[$uid]['completed']++;$paid_total+=$p['paid'];if(!$p['cost_recorded'])continue;$covered_count++;$covered_contract+=$p['contract_revenue'];$covered_paid+=$p['paid'];$cost_total+=$p['direct_cost'];if($p['status']==='completed')$completed_covered++;$key=$p['service']?:'custom';$label=$services[$key]??($key?:'Other / Custom Project');if(!isset($service[$key]))$service[$key]=array('label'=>$label,'projects'=>0,'revenue'=>0.0,'paid'=>0.0,'cost'=>0.0,'profit'=>0.0);$service[$key]['projects']++;$service[$key]['revenue']+=$p['contract_revenue'];$service[$key]['paid']+=$p['paid'];$service[$key]['cost']+=$p['direct_cost'];$service[$key]['profit']+=$p['contract_profit'];}
 foreach($service as &$s)$s['margin']=$s['revenue']>0?($s['profit']/$s['revenue'])*100:null;unset($s);uasort($service,function($a,$b){return $b['profit']<=>$a['profit'];});foreach($clients as $uid=>&$c){$u=$uid?get_userdata($uid):false;$c['name']=$u?$u->display_name:'Unknown Client';$c['share']=$paid_total>0?($c['paid']/$paid_total)*100:0;}unset($c);uasort($clients,function($a,$b){return $b['paid']<=>$a['paid'];});$top_client=$clients?reset($clients):array();$contract_profit=$covered_contract-$cost_total;$margin=$covered_contract>0?($contract_profit/$covered_contract)*100:null;$cost_coverage=count($q->posts)>0?($covered_count/count($q->posts))*100:0;$concentration=(float)($top_client['share']??0);$risk='Balanced';if($concentration>=50)$risk='High concentration';elseif($concentration>=30)$risk='Moderate concentration';return array('project_count'=>count($q->posts),'cost_covered_projects'=>$covered_count,'cost_coverage_percent'=>$cost_coverage,'covered_contract_revenue'=>$covered_contract,'covered_paid'=>$covered_paid,'direct_cost'=>$cost_total,'contract_profit'=>$contract_profit,'margin_percent'=>$margin,'paid_total'=>$paid_total,'services'=>$service,'clients'=>$clients,'top_client'=>$top_client,'revenue_concentration'=>$concentration,'concentration_risk'=>$risk,'completed_cost_covered'=>$completed_covered,'projects'=>$projects);
}

function tuff_beatz_v1411_profitability_panel(){if(!is_page('business-command')||!is_user_logged_in()||!function_exists('tuff_beatz_is_producer_user')||!tuff_beatz_is_producer_user())return;$x=tuff_beatz_v1411_profitability_intelligence();$money=function($n){return function_exists('tuff_beatz_money')?tuff_beatz_money($n):'$'.number_format((float)$n,2);};$margin=$x['margin_percent']===null?'—':number_format((float)$x['margin_percent'],1).'%';$services=array_slice($x['services'],0,5,true);$clients=array_slice($x['clients'],0,5,true);ob_start();?><section class="tb-v1411-profit"><div class="tb-v1411-head"><div><small>PROFITABILITY INTELLIGENCE • V14.11</small><h3>Margin, Client Value & Concentration</h3><p>Profitability uses only projects with a recorded direct-cost basis. Unrecorded projects are excluded from margin calculations.</p></div><div class="tb-v1411-coverage"><span>COST COVERAGE</span><strong><?php echo esc_html(number_format((float)$x['cost_coverage_percent'],0));?>%</strong><em><?php echo esc_html((string)$x['cost_covered_projects']);?> / <?php echo esc_html((string)$x['project_count']);?> projects</em></div></div><div class="tb-v1411-kpis"><article><small>COVERED CONTRACT REVENUE</small><strong><?php echo esc_html($money($x['covered_contract_revenue']));?></strong><span>Projects with cost basis</span></article><article><small>RECORDED DIRECT COST</small><strong><?php echo esc_html($money($x['direct_cost']));?></strong><span>Producer-entered project costs</span></article><article><small>CONTRACT CONTRIBUTION</small><strong><?php echo esc_html($money($x['contract_profit']));?></strong><span>Revenue less recorded direct cost</span></article><article><small>CONTRIBUTION MARGIN</small><strong><?php echo esc_html($margin);?></strong><span>Not net profit; overhead excluded</span></article><article><small>TOP CLIENT SHARE</small><strong><?php echo esc_html(number_format((float)$x['revenue_concentration'],1));?>%</strong><span><?php echo esc_html($x['concentration_risk']);?></span></article><article><small>TOP CLIENT LTV</small><strong><?php echo esc_html($money($x['top_client']['paid']??0));?></strong><span><?php echo esc_html($x['top_client']['name']??'No client data');?></span></article></div><div class="tb-v1411-columns"><div><div class="tb-v1411-title"><small>SERVICE ECONOMICS</small><strong>Recorded-Cost Profitability</strong></div><?php if($services):foreach($services as $s):?><div class="tb-v1411-row"><span><b><?php echo esc_html($s['label']);?></b><small><?php echo esc_html((string)$s['projects']);?> covered project(s)</small></span><span><b><?php echo esc_html($money($s['profit']));?></b><small><?php echo $s['margin']===null?'No revenue':esc_html(number_format((float)$s['margin'],1).'% margin');?></small></span></div><?php endforeach;else:?><p class="tb-v1411-empty">Record project cost bases to unlock service profitability.</p><?php endif;?></div><div><div class="tb-v1411-title"><small>CLIENT VALUE</small><strong>Collected Revenue Concentration</strong></div><?php if($clients):foreach($clients as $c):?><div class="tb-v1411-row"><span><b><?php echo esc_html($c['name']);?></b><small><?php echo esc_html((string)$c['projects']);?> project(s) • <?php echo esc_html((string)$c['completed']);?> completed</small></span><span><b><?php echo esc_html($money($c['paid']));?></b><small><?php echo esc_html(number_format((float)$c['share'],1));?>% of collected revenue</small></span></div><?php endforeach;else:?><p class="tb-v1411-empty">No client payment history recorded yet.</p><?php endif;?></div></div></section><?php $html=ob_get_clean();?><script>document.addEventListener('DOMContentLoaded',function(){var anchor=document.querySelector('.tb-v1410-forecast')||document.querySelector('.tb-v149-intel')||document.querySelector('.tb-biz-kpis');if(!anchor||document.querySelector('.tb-v1411-profit'))return;var box=document.createElement('div');box.innerHTML=<?php echo wp_json_encode($html);?>;anchor.insertAdjacentElement('afterend',box.firstElementChild);var eye=document.querySelector('.tb-biz-hero .eyebrow');if(eye)eye.textContent='TUFF BEATZ • STUDIO BUSINESS OS V14.11';});</script><?php }
add_action('wp_footer','tuff_beatz_v1411_profitability_panel',11);
function tuff_beatz_v1411_profitability_css(){if(!is_page('business-command'))return;wp_add_inline_style('tuff-beatz-business-command','.tb-v1411-profit{margin-top:18px;padding:20px;border:1px solid rgba(216,180,90,.13);border-radius:18px;background:linear-gradient(145deg,rgba(216,180,90,.028),rgba(255,255,255,.012))}.tb-v1411-head{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;padding-bottom:16px;border-bottom:1px solid rgba(255,255,255,.05)}.tb-v1411-head small,.tb-v1411-kpis small,.tb-v1411-title small{display:block;color:#8f7744;font-size:.52rem;letter-spacing:.13em}.tb-v1411-head h3{margin:4px 0;color:#dfd6c2;font-family:Cinzel,serif}.tb-v1411-head p{margin:5px 0 0;max-width:720px;color:#716a5e;font-size:.6rem;line-height:1.5}.tb-v1411-coverage{text-align:right}.tb-v1411-coverage span,.tb-v1411-coverage strong,.tb-v1411-coverage em{display:block}.tb-v1411-coverage span{color:#716a5e;font-size:.5rem;letter-spacing:.1em}.tb-v1411-coverage strong{margin:4px 0;color:#e3c66d;font-family:Cinzel,serif;font-size:1.5rem}.tb-v1411-coverage em{color:#70695e;font-size:.52rem;font-style:normal}.tb-v1411-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:14px}.tb-v1411-kpis article{padding:14px;border:1px solid rgba(255,255,255,.05);border-radius:13px;background:rgba(255,255,255,.014)}.tb-v1411-kpis strong,.tb-v1411-kpis span{display:block}.tb-v1411-kpis strong{margin:7px 0 3px;color:#e2c66c;font-family:Cinzel,serif}.tb-v1411-kpis span{color:#6e675d;font-size:.55rem}.tb-v1411-columns{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}.tb-v1411-columns>div{padding:15px;border:1px solid rgba(255,255,255,.05);border-radius:14px;background:#0b0b0b}.tb-v1411-title{padding-bottom:10px;border-bottom:1px solid rgba(255,255,255,.05)}.tb-v1411-title strong{display:block;margin-top:4px;color:#d8cfbc;font-family:Cinzel,serif;font-size:.8rem}.tb-v1411-row{display:flex;justify-content:space-between;gap:14px;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.04)}.tb-v1411-row:last-child{border-bottom:0}.tb-v1411-row>span:last-child{text-align:right}.tb-v1411-row b,.tb-v1411-row small{display:block}.tb-v1411-row b{color:#cfc4b0;font-size:.65rem}.tb-v1411-row>span:last-child b{color:#dfc36a}.tb-v1411-row small{margin-top:3px;color:#6c665c;font-size:.53rem}.tb-v1411-empty{color:#70695e;font-size:.6rem}@media(max-width:900px){.tb-v1411-kpis{grid-template-columns:repeat(2,1fr)}.tb-v1411-columns{grid-template-columns:1fr}}@media(max-width:620px){.tb-v1411-head{align-items:flex-start;flex-direction:column}.tb-v1411-coverage{text-align:left}.tb-v1411-kpis{grid-template-columns:1fr}}');}
